export function layout(width,height){const stacked=width<650,compact=stacked&&height<500,short=height<300;return {width,height,stacked,compact,short,x:stacked?width*.08:width*.06,w:stacked?width*.74:width*.43,y:compact?height*.4:stacked?height*.4:short?158:height*.61,depth:compact||short?42:65,skew:stacked?width*.08:width*.035,mx:stacked?width*.1:width*.62,my:compact?height-168:stacked?height*.61:short?72:height*.22,mw:stacked?width*.8:width*.31,ch:compact||short?12:stacked?20:23};}
